INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_ni_boost_item_cspu_nd PARTITION (grass_region = ${grass_region}, regional_date = ${local_date})
select
     item_id
    ,sum(cspu_imp_cnt)   as cspu_imp_cnt_7d
    ,sum(cspu_click_cnt) as cspu_click_cnt_7d
    ,sum(cspu_order_cnt) as cspu_order_cnt_7d
    ,count(regional_date) as cspu_cover_days
from(
    select
        *
       ,row_number() over (partition by item_id order by regional_date desc) as rn
    from srdi_mart.dws_sr_data_warehouse_ni_boost_item_cspu_1d
    WHERE grass_region IN (${grass_region}) AND regional_date between date_add(${local_date}, -29) and ${local_date}
) a
where rn <= 7 -- 尽可能凑够7天的有覆盖天数，让指标最大程度置信
group by item_id
;
